var n=`0712-poulet-dg`;var i=`world-0712`;var a=`CM`;var o=`central-africa`;var r=4;var s=83;var g={en:`Poulet DG`,ua:`Курка DG`};var l={en:`Poulet DG is a Cameroon classic prepared with chicken thigh, garlic, ginger root, plantain. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Курка DG, страва кухні країни Камерун зі складниками: куряче стегно, часник, корінь імбиру, плантан. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 25 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 25 хвилин.`,t:[`marinating`],m:25,i:[[`chicken-thigh`,820,`g`],[`garlic`,4,`clove`],[`ginger-root`,25,`g`],[`ground-white-pepper`,5,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 17 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 17 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:17,i:[[`plantain`,500,`g`],[`peanut-oil`,75,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 13 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 13 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:13,i:[[`yellow-onion`,200,`g`],[`carrot`,230,`g`],[`green-bell-pepper`,220,`g`],[`tomato`,270,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 24 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 24 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:24,i:[[`chicken-stock`,380,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,18,`g`]]}];var h={slug:n,id:i,country:`CM`,region:o,servings:4,minutes:83,title:g,text:l,steps:d};export{a as country,h as default,i as id,s as minutes,o as region,r as servings,n as slug,d as steps,l as text,g as title};